package com.theaimartco.taim;

import android.Manifest;
import android.content.pm.PackageManager;
import android.os.Bundle;
import android.view.View;
import com.google.android.gms.maps.*;
import com.google.android.gms.maps.model.*;
import org.json.*;
import java.util.*;

/**
 * Google Maps extension: native-view factory {@code taim.map}. Generated by project.py --maps,
 * which reads the API key from TAIM_MAPS_API_KEY at build time (never committed).
 *
 * Properties: latitude, longitude, zoom (camera; applied when {@code cameraToken} changes or on
 * first load), mapType (normal|satellite|terrain|hybrid), lite (static bitmap mode),
 * myLocation (requires granted location permission), markers [{id,latitude,longitude,title?}].
 * Events: ready, cameraIdle {latitude,longitude,zoom}, mapClick {latitude,longitude}, markerClick {id}.
 *
 * Composition: MapView renders through a SurfaceView, so this factory is registered with
 * registerTaimSurfaceViewFactory. The map composes above Taim's surface: Taim content drawn over the
 * slot is hidden (modal sheets hide the slot). {@code lite: true} renders a bitmap with no such limit.
 */
public final class TaimMaps implements TaimExtension {
    @Override public void attach(TaimActivity activity){activity.registerTaimSurfaceViewFactory("taim.map",Instance::new);}

    static final class Instance implements TaimNativeViewFactory.Instance, OnMapReadyCallback {
        private final TaimActivity activity;private final TaimNativeViewFactory.Host host;
        private final MapView view;private GoogleMap map;private JSONObject props;
        private final Map<String,Marker> markers=new HashMap<>();
        private long cameraToken=Long.MIN_VALUE;private boolean disposed;

        Instance(TaimActivity activity,JSONObject properties,TaimNativeViewFactory.Host host)throws Exception {
            this.activity=activity;this.host=host;validate(properties);props=properties;
            GoogleMapOptions options=new GoogleMapOptions().liteMode(properties.optBoolean("lite",false))
                .camera(CameraPosition.fromLatLngZoom(new LatLng(properties.getDouble("latitude"),properties.getDouble("longitude")),(float)properties.optDouble("zoom",12)));
            view=new MapView(activity,options);
            view.onCreate(new Bundle());view.onStart();view.onResume();
            view.getMapAsync(this);
        }
        @Override public View view(){return view;}

        private static void validate(JSONObject p)throws JSONException {
            for(Iterator<String> keys=p.keys();keys.hasNext();)if(!keys.next().matches("latitude|longitude|zoom|cameraToken|mapType|lite|myLocation|markers"))throw new IllegalArgumentException();
            double lat=p.getDouble("latitude"),lng=p.getDouble("longitude"),zoom=p.optDouble("zoom",12);
            if(lat<-90 || lat>90 || lng<-180 || lng>180 || zoom<1 || zoom>21)throw new IllegalArgumentException();
            if(!p.optString("mapType","normal").matches("normal|satellite|terrain|hybrid"))throw new IllegalArgumentException();
            JSONArray m=p.optJSONArray("markers");if(m!=null && m.length()>500)throw new IllegalArgumentException();
        }

        @Override public void update(JSONObject properties)throws Exception {validate(properties);props=properties;apply();}

        @Override public void onMapReady(GoogleMap ready){
            if(disposed)return;map=ready;
            map.setOnCameraIdleListener(()->{CameraPosition c=map.getCameraPosition();emit("cameraIdle","latitude",c.target.latitude,"longitude",c.target.longitude,"zoom",(double)c.zoom);});
            map.setOnMapClickListener(at->emit("mapClick","latitude",at.latitude,"longitude",at.longitude));
            map.setOnMarkerClickListener(marker->{Object id=marker.getTag();if(id!=null)emit("markerClick","id",id);return false;});
            apply();emit("ready");
        }

        private void apply(){
            if(map==null)return;
            try{
                String type=props.optString("mapType","normal");
                map.setMapType(type.equals("satellite")?GoogleMap.MAP_TYPE_SATELLITE:type.equals("terrain")?GoogleMap.MAP_TYPE_TERRAIN:type.equals("hybrid")?GoogleMap.MAP_TYPE_HYBRID:GoogleMap.MAP_TYPE_NORMAL);
                boolean location=props.optBoolean("myLocation",false) && (activity.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED || activity.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED);
                try{map.setMyLocationEnabled(location);}catch(SecurityException ignored){}
                long token=props.optLong("cameraToken",0);
                if(token!=cameraToken){cameraToken=token;map.moveCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(props.getDouble("latitude"),props.getDouble("longitude")),(float)props.optDouble("zoom",12)));}
                Set<String> wanted=new HashSet<>();JSONArray list=props.optJSONArray("markers");
                if(list!=null)for(int i=0;i<list.length();i++){
                    JSONObject m=list.getJSONObject(i);String id=m.getString("id");if(!id.matches("[A-Za-z0-9._-]{1,64}"))continue;
                    wanted.add(id);LatLng at=new LatLng(m.getDouble("latitude"),m.getDouble("longitude"));
                    String title=m.isNull("title")?null:m.optString("title",null);
                    Marker existing=markers.get(id);
                    if(existing==null){Marker created=map.addMarker(new MarkerOptions().position(at).title(title));if(created!=null){created.setTag(id);markers.put(id,created);}}
                    else{existing.setPosition(at);existing.setTitle(title);}
                }
                for(Iterator<Map.Entry<String,Marker>> it=markers.entrySet().iterator();it.hasNext();){Map.Entry<String,Marker> e=it.next();if(!wanted.contains(e.getKey())){e.getValue().remove();it.remove();}}
            }catch(JSONException ignored){}
        }

        /** Emit {type, key1, value1, ...}; JSON errors and disposed hosts are ignored. */
        private void emit(String type,Object... pairs){
            try{JSONObject e=new JSONObject().put("type",type);for(int i=0;i+1<pairs.length;i+=2)e.put((String)pairs[i],pairs[i+1]);host.emit(e);}
            catch(JSONException | IllegalStateException ignored){}
        }
        @Override public void resumed(){if(!disposed)view.onResume();}
        @Override public void paused(){if(!disposed)view.onPause();}
        @Override public void dispose(){if(disposed)return;disposed=true;markers.clear();if(map!=null){map.setOnCameraIdleListener(null);map.setOnMapClickListener(null);map.setOnMarkerClickListener(null);}view.onPause();view.onStop();view.onDestroy();}
    }
}
